/**
 * Auto-derives bull-case / bear-case bullet points from the real,
 * already-fetched quantitative data (financial health, valuation, analyst
 * consensus, insider sentiment) using fixed, explainable thresholds.
 *
 * This exists because no free API provides genuine analyst-written bull/bear
 * thesis prose (that's paywalled research) — rather than fabricate a
 * narrative, each point here is traceable back to a real number with its own
 * source and date. The result is explicitly marked `autoGenerated: true` so
 * nobody mistakes it for human analyst commentary.
 */

const today = () => new Date().toISOString().slice(0, 10);

function parseNumeric(value) {
  if (value == null) return null;
  const n = Number.parseFloat(String(value).replace(/[%,]/g, ''));
  return Number.isFinite(n) ? n : null;
}

function findMetric(metrics, label) {
  return metrics?.find((m) => m.label === label) ?? null;
}

export function deriveBullBear({ financialHealth, valuation, consensus, insiderSentiment }) {
  const bullPoints = [];
  const bearPoints = [];

  const margin = parseNumeric(findMetric(financialHealth?.metrics, 'Net profit margin')?.value);
  if (margin != null) {
    if (margin >= 15) {
      bullPoints.push(`Net profit margin of ${margin}% is strong, suggesting real pricing power or cost discipline (Financial Modeling Prep, ${today()}).`);
    } else if (margin < 5) {
      bearPoints.push(`Net profit margin of only ${margin}% is thin, leaving little room for error if costs rise or prices fall (Financial Modeling Prep, ${today()}).`);
    }
  }

  const debtEquity = parseNumeric(findMetric(financialHealth?.metrics, 'Debt / Equity')?.value);
  if (debtEquity != null) {
    if (debtEquity < 1) {
      bullPoints.push(`Debt/Equity of ${debtEquity} is low, meaning relatively little leverage risk (Financial Modeling Prep, ${today()}).`);
    } else if (debtEquity > 1.5) {
      bearPoints.push(`Debt/Equity of ${debtEquity} is elevated, increasing financial risk if earnings weaken (Financial Modeling Prep, ${today()}).`);
    }
  }

  const currentRatio = parseNumeric(findMetric(financialHealth?.metrics, 'Current ratio')?.value);
  if (currentRatio != null) {
    if (currentRatio >= 1.5) {
      bullPoints.push(`Current ratio of ${currentRatio} indicates strong short-term liquidity (Financial Modeling Prep, ${today()}).`);
    } else if (currentRatio < 1) {
      bearPoints.push(`Current ratio of ${currentRatio} is below 1, signalling possible short-term liquidity pressure (Financial Modeling Prep, ${today()}).`);
    }
  }

  const pe = parseNumeric(findMetric(valuation?.metrics, 'P/E (TTM)')?.value);
  if (pe != null) {
    if (pe > 0 && pe < 15) {
      bullPoints.push(`P/E (TTM) of ${pe} is low relative to typical market levels, which can mean the stock is inexpensive relative to earnings (Financial Modeling Prep, ${today()}).`);
    } else if (pe > 35) {
      bearPoints.push(`P/E (TTM) of ${pe} is high, pricing in significant future growth — a miss on expectations could hit the share price hard (Financial Modeling Prep, ${today()}).`);
    }
  }

  if (consensus) {
    if (consensus.rating === 'Strong Buy' || consensus.rating === 'Buy') {
      bullPoints.push(`Analyst consensus is "${consensus.rating}" across ${consensus.numberOfAnalysts} analysts (Finnhub, ${consensus.asOf}).`);
    } else if (consensus.rating === 'Sell' || consensus.rating === 'Strong Sell') {
      bearPoints.push(`Analyst consensus is "${consensus.rating}" across ${consensus.numberOfAnalysts} analysts (Finnhub, ${consensus.asOf}).`);
    }
    if (consensus.trendDirection === 'improving') {
      bullPoints.push(`Analyst sentiment has improved month-on-month (Finnhub, ${consensus.asOf}).`);
    } else if (consensus.trendDirection === 'worsening') {
      bearPoints.push(`Analyst sentiment has worsened month-on-month (Finnhub, ${consensus.asOf}).`);
    }
  }

  if (insiderSentiment && insiderSentiment.mspr != null) {
    if (insiderSentiment.mspr > 0) {
      bullPoints.push(`Insider sentiment is positive (MSPR +${insiderSentiment.mspr}) as of ${insiderSentiment.month} (Finnhub, ${insiderSentiment.asOf}).`);
    } else if (insiderSentiment.mspr < 0) {
      bearPoints.push(`Insider sentiment is negative (MSPR ${insiderSentiment.mspr}) as of ${insiderSentiment.month} (Finnhub, ${insiderSentiment.asOf}).`);
    }
  }

  const note =
    'Auto-generated from the live data on this page using fixed, explainable rules (margins, leverage, liquidity, valuation, analyst consensus, insider sentiment) — not human analyst commentary.';
  const source = 'Derived from the data on this page (see Financial health / Valuation / Analyst consensus sections)';

  return {
    bullCase: bullPoints.length > 0 ? { points: bullPoints, autoGenerated: true, note, source, asOf: today() } : null,
    bearCase: bearPoints.length > 0 ? { points: bearPoints, autoGenerated: true, note, source, asOf: today() } : null,
  };
}
